import hashlib, json
from pathlib import Path
source = Path('products/services/uk-data-reconciliation-lot/raw/tender-feed.json')
raw = source.read_bytes()
package = json.loads(raw)
fields = ('id', 'title', 'description', 'status', 'mainProcurementCategory', 'tenderPeriod', 'participationPeriod', 'submissionMethod', 'submissionMethodDetails')
def item_summary(item):
    return {key: item[key] for key in ('description', 'classification', 'additionalClassifications', 'relatedLot') if key in item}
rows = []
for release in package.get('releases', []):
    tender = release.get('tender') or {}
    rows.append({'notice_id': release.get('id'), 'ocid': release.get('ocid'), 'release_date': release.get('date'), 'tags': release.get('tag'), 'tender': {key: tender[key] for key in fields if key in tender}, 'lots': [{key: lot[key] for key in ('id', 'title', 'description', 'status', 'tenderPeriod', 'value') if key in lot} for lot in tender.get('lots', [])], 'items': [item_summary(item) for item in tender.get('items', [])]})
report = {'source': str(source), 'sha256': hashlib.sha256(raw).hexdigest(), 'release_count': len(rows), 'scope': 'Single captured feed page. Missing fields are unknown. Use original notice terms to verify any live, separately quotable work.', 'releases': rows}
out = Path('products/services/uk-data-reconciliation-lot/director-lot-fields.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
assert json.loads(out.read_text(encoding='utf-8')) == report
print(json.dumps({'output': str(out), 'release_count': len(rows), 'structured_lot_count': sum(len(row['lots']) for row in rows)}))
